<?php require 'includes/conexao.php'; require 'includes/verificar_login.php'; exigir_login(); $ranking=$pdo->query('SELECT u.nome,p.xp,p.nivel,COALESCE(SUM(r.pontuacao),0) pontos FROM usuarios u LEFT JOIN progresso p ON p.usuario_id=u.id LEFT JOIN resultados r ON r.usuario_id=u.id WHERE u.tipo="aluno" GROUP BY u.id,p.xp,p.nivel ORDER BY pontos DESC,xp DESC')->fetchAll(); $titulo='Ranking'; $home='dashboard.php'; include 'includes/header.php'; ?><div class="section-heading"><div><div class="eyebrow">Placar da arena</div><h1 style="font-size:4rem">Ranking</h1><p>Veja quem está brilhando e acompanhe sua posição.</p></div></div><div class="card"><table><thead><tr><th>#</th><th>Jogador</th><th>Nível</th><th>XP</th><th>Pontos</th></tr></thead><tbody><?php foreach($ranking as $pos=>$j): ?><tr><td class="rank-number"><?= $pos<3 ? ['🥇','🥈','🥉'][$pos] : $pos+1 ?></td><td><?= htmlspecialchars($j['nome']) ?><?= $j['nome']===$_SESSION['nome'] ? ' <span class="tag">você</span>' : '' ?></td><td><?= $j['nivel'] ?></td><td><?= $j['xp'] ?></td><td><strong><?= $j['pontos'] ?></strong></td></tr><?php endforeach; ?></tbody></table></div><?php include 'includes/footer.php'; ?>
